<script setup lang="ts">
import { searchQueries } from '../utils/searchTrace'; import { useChatStore } from '../stores/chat'; import { computed, ref } from 'vue'; import type { Attachment, Message, Usage } from '../types'; import { renderMarkdown } from '../utils/markdown'
const props = defineProps<{ message: Message; canRegenerate?: boolean; codeAttachments?: Attachment[]; usage?: Usage }>(); const emit = defineEmits<{ regenerate: []; preview: [attachment: Attachment]; diff: [attachment: Attachment, proposed: string] }>(); const html = computed(() => renderMarkdown(props.message.content)); const copied = ref(false); const copy = async () => { await navigator.clipboard.writeText(props.message.content); copied.value = true; setTimeout(() => copied.value = false, 1400) }
const chat = useChatStore()
const editing = ref(false), editedText = ref('')
const edit = () => {editedText.value=props.message.content;editing.value=true}
const article = ref<HTMLElement>()
const quote = () => {const selection=window.getSelection();const selected=selection?.anchorNode && selection.focusNode && article.value?.querySelector('.markdown')?.contains(selection.anchorNode) && article.value?.querySelector('.markdown')?.contains(selection.focusNode) ? selection.toString().trim() : '';chat.quote(props.message, selected || undefined)}
const versions = computed(() => chat.versions(props.message))
const versionIndex = computed(() => versions.value.findIndex(m => m.id === props.message.id))
const proposal = computed(() => { const block=/```(?:[\w.+-]+)?\s*\n([\s\S]*?)\n```/.exec(props.message.content); return block?.[1] || '' })
const domain = (url: string) => { try { return new URL(url).hostname } catch { return url } }
const reviewCode = () => { const files=props.codeAttachments || []; if (!proposal.value || !files.length) return; const chosen=files.length===1?files[0]:files.find(f=>f.name===window.prompt(`选择要比较的文件名：\n${files.map(x=>x.name).join('\n')}`,files.at(-1)?.name)); if(chosen)emit('diff',chosen,proposal.value) }
</script>
<template><article ref="article" :class="['message', message.role]"><div class="avatar">{{ message.role === 'user' ? '你' : '✦' }}</div><div class="message-body"><div class="message-name">{{ message.role === 'user' ? '你' : '助手' }}</div><div v-if="message.attachments?.length" class="attachment-list"><template v-for="item in message.attachments" :key="item.id"><button v-if="item.kind === 'document' || item.kind === 'code'" type="button" class="attachment-card attachment-open" :aria-label="`预览 ${item.name}`" @click="emit('preview', item)"><span>▤</span><div><strong>{{ item.name }}</strong><small>点击预览{{ item.kind === 'code' ? '代码' : '文档' }}</small></div></button><div v-else class="attachment-card"><img :src="`data:${item.mime};base64,${item.data}`" :alt="item.name"/><div><strong>{{ item.name }}</strong><small>图片</small></div></div></template></div><blockquote v-for="reference in message.references" :key="reference.messageId" class="message-reference"><button :disabled="chat.loading" @click="chat.jumpNode(reference.messageId)">查看引用来源 · {{ reference.messageId.slice(0,8) }}</button><p>{{ reference.text }}</p></blockquote><details v-if="message.searchTrace && message.searchTrace.status !== 'off'"><summary>搜索过程 · {{ message.searchTrace.provider }} · {{ ({completed:'完成',cancelled:'已停止',searching:'搜索中',generating:'正在生成回答'} as Record<string,string>)[message.searchTrace.status] || message.searchTrace.status }}</summary><p v-if="searchQueries(message).length">搜索关键词：{{ searchQueries(message).join(' · ') }}</p><p v-else>由 Provider 执行搜索；未返回关键词</p><p>检索资料 → 返回来源 → 结合来源生成回答</p><p>返回 {{ message.searchTrace.sources }} 个来源；正文 [编号] 对应下方来源卡片。</p><button :disabled="chat.loading" @click="chat.reSearch(message)">重新搜索并生成新版本</button></details><form v-if="editing" class="message-edit" @submit.prevent="chat.editResend(message,editedText); editing=false"><textarea v-model="editedText" rows="5" aria-label="编辑历史消息"/><button type="submit" :disabled="chat.loading || !editedText.trim()">创建新分支并重发</button><button type="button" @click="editing=false">取消</button></form><div v-if="message.content" class="markdown" v-html="html"/><div v-else-if="message.pending" class="thinking"><i/><i/><i/> 正在思考</div><div v-if="message.sources?.length" class="sources"><details v-for="(source,index) in message.sources" :key="source.url" class="source-detail"><summary>[{{ index+1 }}] {{ source.citation ? `(${source.citation}) ` : '' }}{{ source.title }} · {{ domain(source.url) }}</summary><a :key="source.url" :href="source.url" target="_blank" rel="noreferrer" class="source-card"><strong>[{{ index+1 }}] {{ source.citation ? `(${source.citation}) ` : '' }}{{ source.title }}</strong><small>{{ domain(source.url) }}</small><span>{{ source.snippet }}</span></a></details></div><div v-if="message.content && !message.pending" class="message-tools"><button :disabled="chat.loading" @click="quote">引用 / 引用选中文本</button><button v-if="message.role === 'user'" :disabled="chat.loading" @click="edit">编辑并重发</button><button v-if="message.role === 'assistant'" :disabled="chat.loading" @click="chat.continueReply(message)">继续生成</button><template v-if="versions.length > 1"><button :disabled="chat.loading || versionIndex <= 0" @click="chat.selectVersion(message,-1)">‹</button><span>{{ versionIndex + 1 }}/{{ versions.length }}</span><button :disabled="chat.loading || versionIndex >= versions.length-1" @click="chat.selectVersion(message,1)">›</button></template><button @click="copy">{{ copied ? '已复制' : '⧉ 复制' }}</button><button v-if="proposal && codeAttachments?.length" @click="reviewCode">查看代码 Diff</button><button v-if="canRegenerate" @click="emit('regenerate')">↻ 重新生成</button></div><small v-if="usage">输入 {{ usage.inputTokens }} · 输出 {{ usage.outputTokens }} · 思考约 {{ usage.thinkingTokens }} Token · {{ (usage.durationMs / 1000).toFixed(1) }}s · ${{ usage.estimatedCost.toFixed(4) }}</small></div></article></template>
